/**
 * Retrieves the most recently added formatting element with the specified node name from the list of formatting elements.
 * The search is performed in reverse order, starting from the last element in the list.
 * If a null element (indicating a scope marker) is encountered during the search, the search terminates immediately.
 * 
 * @param nodeName The name of the node to search for.
 * @return The Element with the specified node name if found; otherwise, null.
 */
Element getActiveFormattingElement(String nodeName) {
    for (int pos = formattingElements.size() - 1; pos >= 0; pos--) {
        Element next = formattingElements.get(pos);
        if (next == null) // scope marker
            break;
        else if (next.nodeName().equals(nodeName))
            return next;
    }
    return null;
}
```
